}\\
&= 
\underset{\substack{\rho: CC_F^{i}(\rho(i_i \mapsto a_i),\rho(i_i \mapsto 1-a_i) )= l_i\\ \rho \in \mathcal{A}_{i+1}}} {\sum} \frac{Pr[\rho]}{\underset{\rho \in \mathcal{A}_{i+1}} {\sum} Pr[\rho]}
\end{align*}

where 
$  
\mathcal{A}_{i+1} := \{\rho: CC_F^{j}(\rho\circ \sigma_{i+1 \to j}, \rho \circ \sigma_{i+1 \to j}')= l_j \ \forall i+1\leq j \leq t; \\
F|_{\rho\circ \sigma_{i+1 \to t}} \equiv 0, F|_{\rho\circ \sigma_{i+1 \to t}'}\equiv 1\;\\
x_{i_{i+1}}=\ldots= x_{i_t} = *\\ 
x_{i_1} = a_1, \dots, x_{i_i}=a_i \}
$




