\underset{\substack{\rho: CC_F^{j}(\rho\circ \sigma_j, \rho \circ \sigma_j')= l_j\\ \forall i\leq j \leq t\\ F|_{\rho\circ \sigma_t} \equiv 0, F|_{\rho\circ \sigma_t'}\equiv 1\\x_{i_1}=\ldots= x_{i_t} = *}} {\sum} Pr[\rho \circ \sigma_{i}']
}
