}
&= \
\frac{
\underset{\substack{\rho: CC_F^{j}(\rho(i_i \mapsto a_i)\circ \sigma_{i+1 \to j}, \rho(i_i \mapsto a_i) \circ \sigma_{i+1 \to j}')= l_j\\ \forall i+1\leq j \leq t\\ F|_{\rho(i_i \mapsto a_i)\circ \sigma_{i+1 \to t}} \equiv 0, F|_{\rho(i_i \mapsto a_i)\circ \sigma_{i+1 \to t}'}\equiv 1\\x_{i_{i+1}}=\ldots= x_{i_t} = *\\ x_{i_1} = a_1, \dots, x_{i_i}=a_i }} {\sum} Pr[\rho]
}
{
\underset{\substack{\rho: CC_F^{j}(\rho(i_i \mapsto a_i)\circ \sigma_{i+1 \to j}, \rho(i_i \mapsto a_i) \circ \sigma_{i+1 \to j}')= l_j\\ \forall i+1\leq j \leq t\\F|_{\rho\circ \sigma_{i+1 \to t}} \equiv 0, F|_{\rho\circ \sigma_{i+1 \to t}'}\equiv 1\\x_{i_{i+1}}=\ldots= x_{i_t} = *\\ x_{i_1} = a_1, \dots, x_{i_i}=a_i }} {\sum} Pr[\rho ]
}\\
